-- N1/N2 문법 추가 (2026-06-27 batch-b)
-- NOT NULL: pattern, meaning_ko, meaning_ja, formation, example_sentences. 기존 패턴 제외, 맨 뒤 append

-- ── N1 문법 16개 ──
WITH base AS (SELECT COALESCE(max(seq),0) AS m FROM jlpt_grammar WHERE jlpt_level='N1'),
src AS (
  SELECT * FROM (VALUES
    (1,'〜をおいてほかにいない','~외에 다른 사람은 없다 (유일한 적임자임을 강조)','それ以外に適任者はいないという強い断定を表す。','名詞 + をおいてほかにいない','をおいてほかにいない','この仕事を任せるなら、彼をおいてほかにいない。','이 일을 맡긴다면 그를 두고 다른 사람은 없다.','emphasis'),
    (2,'〜想像にかたくない','~는 어렵지 않게 상상할 수 있다','容易に想像できるという意味を表す。','名詞 + は想像にかたくない / 動詞辞書形 + のは想像にかたくない','想像にかたくない','彼女がどれほど苦労したか、想像にかたくない。','그녀가 얼마나 고생했는지 어렵지 않게 상상할 수 있다.','conjecture'),
    (3,'〜でなくてなんだろう','~이 아니고 무엇이겠는가 (강한 긍정·단정)','まさにそれだという強い断定・感動を表す。','名詞 + でなくてなんだろう','でなくてなんだろう','彼が一人で成し遂げたこの成果は、奇跡でなくてなんだろう。','그가 혼자 이루어낸 이 성과는 기적이 아니고 무엇이겠는가.','emphasis'),
    (4,'〜ればこそ','~이기 때문에 비로소, ~하기 때문에야말로','それだけが理由・根拠であることを強調する。','動詞ば形 + こそ','ればこそ','努力すればこそ、夢を実現することができるのだ。','노력하기 때문에 비로소 꿈을 실현할 수 있는 것이다.','reason'),
    (5,'〜あるまじき','~해서는 안 될, ~에 있을 수 없는 (비난·금지)','その立場の人として許されない言動を非難する。','名詞 + にあるまじき + 名詞','あるまじき','教師にあるまじき行為で、厳しく処分された。','교사로서 있어서는 안 될 행위로 엄하게 처벌받았다.','obligation'),
    (6,'〜めいた','~같은, ~스러운, ~을 연상시키는','そのような感じ・要素を帯びていることを表す。','名詞 + めいた + 名詞','めいた','彼女の言葉には、謎めいた雰囲気があった。','그녀의 말에는 수수께끼 같은 분위기가 있었다.','manner'),
    (7,'〜ことなしに','~하지 않고서는, ~없이는','それをしなければ後が成立しないことを表す。','動詞辞書形 + ことなしに','ことなしに','努力することなしに、夢を実現することはできない。','노력하지 않고서는 꿈을 실현할 수 없다.','condition'),
    (8,'〜いうまでもなく','말할 것도 없이, 당연히','言う必要もないほど当然であることを表す。','名詞 + はいうまでもなく','いうまでもなく','健康が大切なことは、いうまでもなく、皆が理解している。','건강이 중요하다는 것은 말할 것도 없이 모두가 이해하고 있다.','emphasis'),
    (9,'〜に先立ち','~에 앞서, ~보다 먼저','ある事の前に準備として行うことを表す。','名詞/動詞辞書形 + に先立ち','に先立ち','開会式に先立ち、関係者への説明会が開催された。','개회식에 앞서 관계자들을 위한 설명회가 개최되었다.','time'),
    (10,'〜いかんによっては','~여하에 따라서는, ~에 따라 달라질 수 있다','その内容次第で結果が変わることを表す。','名詞 + (の)いかんによっては','いかんによっては','結果いかんによっては、計画を見直す必要がある。','결과 여하에 따라서는 계획을 재검토할 필요가 있다.','condition'),
    (11,'〜なくして','~없이는, ~가 없으면 (불가능함을 강조)','それがなければ成立しないという条件を表す。','名詞 + なくして(は)','なくして','信頼なくして、良好な人間関係は築けない。','신뢰 없이는 좋은 인간관계를 쌓을 수 없다.','condition'),
    (12,'〜を禁じえない','~을 금할 수 없다, ~을 참을 수 없다','ある感情が自然に湧き上がるのを抑えられない。','名詞 + を禁じえない','を禁じえない','その悲しい知らせに、涙を禁じえなかった。','그 슬픈 소식에 눈물을 금할 수 없었다.','desire'),
    (13,'〜てはじめて','~하고 나서야 비로소 (그때서야 깨달음)','その経験をして初めて気づくことを表す。','動詞て形 + はじめて','てはじめて','失ってはじめて、その大切さに気づいた。','잃고 나서야 비로소 그 소중함을 깨달았다.','time'),
    (14,'〜だにしない','~조차 하지 않다 (전혀 ~하지 않음을 강조)','少しもそうしないという強い否定を表す。','名詞/動詞辞書形 + だにしない','だにしない','そんなことが起こるとは、想像だにしなかった。','그런 일이 일어날 것이라고는 상상조차 하지 않았다.','emphasis'),
    (15,'〜でないまでも','완전히 ~은 아닐지라도, ~까지는 아니더라도','最高の程度ではなくてもある程度はという譲歩を表す。','名詞/な形容詞 + でないまでも','でないまでも','完璧でないまでも、できる限り丁寧に仕上げた。','완벽하지는 않을지라도 가능한 한 정성껏 마무리했다.','degree'),
    (16,'〜からというもの','~한 이후로 줄곧, ~한 이래로 계속','ある時を境にずっと続く状態を表す。','動詞て形 + からというもの','からというもの','転職してからというもの、毎日が充実している。','이직한 이후로 줄곧 매일이 보람차다.','time')
  ) AS v(ord,pattern,meaning_ko,meaning_ja,formation,highlight,ja,ko,category)
  WHERE NOT EXISTS (SELECT 1 FROM jlpt_grammar WHERE jlpt_level='N1' AND pattern=v.pattern)
)
INSERT INTO jlpt_grammar (pattern, meaning_ko, meaning_ja, formation, category, example_sentences, jlpt_level, seq)
SELECT s.pattern, s.meaning_ko, s.meaning_ja, s.formation, s.category,
       jsonb_build_array(jsonb_build_object('ja', s.ja, 'ko', s.ko, 'highlight', s.highlight)),
       'N1', b.m + row_number() OVER (ORDER BY s.ord)
FROM src s CROSS JOIN base b;

-- ── N2 문법 23개 ──
WITH base AS (SELECT COALESCE(max(seq),0) AS m FROM jlpt_grammar WHERE jlpt_level='N2'),
src AS (
  SELECT * FROM (VALUES
    (1,'〜てきた','(변화가) ~해 왔다, 계속 ~해 오고 있다','過去から現在まで変化・継続してきたことを表す。','動詞て形 + きた','してきた','長い年月をかけて、この技術が発展してきた。','오랜 세월에 걸쳐 이 기술이 발전해 왔다.','change'),
    (2,'〜によって','~에 의해, ~에 따라','手段・原因・基準などを表す。','名詞 + によって','によって','この問題の結果は、対処方法によって大きく変わる。','이 문제의 결과는 대처 방법에 따라 크게 달라진다.','manner'),
    (3,'〜にとって','~에게 있어서, ~의 입장에서','ある立場から見た評価・判断を表す。','名詞 + にとって','にとって','子供にとって、自由に遊ぶ時間は大切な学びの場だ。','아이에게 있어서 자유롭게 노는 시간은 소중한 배움의 장이다.','manner'),
    (4,'〜成し得ない','달성할 수 없다, 이룰 수 없다','実現・達成が不可能であることを表す。','名詞 + を成し得ない','成し得ない','チームの協力なしには成し得ない目標だった。','팀의 협력 없이는 이룰 수 없는 목표였다.','ability'),
    (5,'〜からすれば','~의 관점에서 보면, ~으로 판단하면','ある立場・基準から判断することを表す。','名詞 + からすれば','からすれば','経験豊富な彼からすれば簡単なことだろう。','경험이 풍부한 그의 관점에서 보면 간단한 일일 것이다.','manner'),
    (6,'〜からといって〜わけではない','~라고 해서 반드시 ~인 것은 아니다','理由があっても結論が必ずしも成り立たないことを表す。','普通形 + からといって 〜 わけではない','からといって','高いからといって品質がいいわけではない。','비싸다고 해서 반드시 품질이 좋은 것은 아니다.','reason'),
    (7,'〜ものか','결코 ~할 리가 없다, 절대 ~하지 않겠다 (강한 부정)','強い否定・拒否の気持ちを表す。','動詞辞書形 + ものか','ものか','あんなひどいことをした彼を、二度と許すものか。','그런 나쁜 짓을 한 그를 두 번 다시 용서할 리 없다.','emphasis'),
    (8,'〜べきだ','~해야 한다, ~하는 것이 당연하다','当然そうするのが正しいという義務・主張を表す。','動詞辞書形 + べきだ','べきだ','責任ある立場にいる人は規則を守るべきだ。','책임 있는 위치에 있는 사람은 규칙을 지켜야 한다.','obligation'),
    (9,'〜につれて','~함에 따라, ~할수록','一方の変化に伴って他方も変化することを表す。','動詞辞書形/名詞 + につれて','につれて','勉強が進むにつれて、日本語が面白くなった。','공부가 진행될수록 일본어가 재미있어졌다.','change'),
    (10,'〜を契機に','~를 계기로, ~를 기회로','ある出来事をきっかけに変化が起きることを表す。','名詞 + を契機に','を契機に','留学を契機に、将来の目標が明確になった。','유학을 계기로 앞으로의 목표가 뚜렷해졌다.','time'),
    (11,'〜ばかりか','~뿐만 아니라, ~은 물론이고','それだけでなくさらに上のことを付け加える。','名詞/普通形 + ばかりか','ばかりか','彼女は料理ばかりか、掃除も完璧にこなす。','그녀는 요리뿐만 아니라 청소도 완벽하게 해낸다.','listing'),
    (12,'〜を中心に','~를 중심으로','それを中心・基点として物事が展開することを表す。','名詞 + を中心に','を中心に','東京を中心に、多くの企業が集まっている。','도쿄를 중심으로 많은 기업이 모여 있다.','manner'),
    (13,'〜だけあって','~인 만큼, ~답게','それにふさわしい結果が伴うことを表す。','名詞/普通形 + だけあって','だけあって','さすがプロだけあって、その演奏は見事だった。','역시 프로인 만큼 그 연주는 훌륭했다.','reason'),
    (14,'〜はともかく','~는 어쨌든, ~는 제쳐두고','それは別にして本題を述べることを表す。','名詞 + はともかく','はともかく','費用はともかく、この計画は実行すべきだ。','비용은 어쨌든 이 계획은 실행해야 한다.','contrast'),
    (15,'〜さえ','~조차, ~만 있으면','極端な例を挙げて強調する、または最低条件を表す。','名詞 + さえ','さえ','彼女は友達に助けを求めることさえしなかった。','그녀는 친구에게 도움을 청하는 것조차 하지 않았다.','emphasis'),
    (16,'〜にあたって','~에 즈음하여, ~할 때','重要な事を行う際の心構えや準備を表す。','名詞/動詞辞書形 + にあたって','にあたって','新しいプロジェクトを始めるにあたって、計画を立てた。','새 프로젝트를 시작함에 즈음하여 계획을 세웠다.','time'),
    (17,'〜ないわけにはいかない','~하지 않을 수 없다, ~해야만 한다','事情から見てそうせざるを得ないことを表す。','動詞ない形 + わけにはいかない','ないわけにはいかない','頼まれた以上、引き受けないわけにはいかない。','부탁을 받은 이상 맡지 않을 수 없다.','obligation'),
    (18,'〜してしまう','(완전히/돌이킬 수 없게) ~해 버리다','完了、または残念な結果を表す。','動詞て形 + しまう','してしまう','大事な試験なのに、全問答えを間違えてしまった。','중요한 시험인데 모든 문제의 답을 틀려 버렸다.','change'),
    (19,'〜として','~로서, ~의 자격으로','立場・資格・名目を表す。','名詞 + として','として','彼はエンジニアとして会社に貢献している。','그는 엔지니어로서 회사에 공헌하고 있다.','manner'),
    (20,'〜ものがある','~한 면이 있다, ~한 것이 있다','ある性質・印象を強く感じることを表す。','普通形 + ものがある','ものがある','彼女の歌声には聴く人を感動させるものがある。','그녀의 노랫소리에는 듣는 사람을 감동시키는 면이 있다.','emphasis'),
    (21,'〜にかかわらず','~에 관계없이, ~와 상관없이','それに左右されないことを表す。','名詞 + にかかわらず','にかかわらず','年齢にかかわらず、学ぶことに遅すぎない。','나이에 관계없이 배우는 것에 늦은 때는 없다.','condition'),
    (22,'〜ていく','~해 가다, 앞으로도 계속 ~하다','これからも継続・変化していくことを表す。','動詞て形 + いく','ていく','これからも努力を重ね、成長し続けていく。','앞으로도 노력을 거듭하며 계속 성장해 나갈 것이다.','change'),
    (23,'〜をもとに','~를 바탕으로, ~에 근거하여','それを基礎・材料として何かを行うことを表す。','名詞 + をもとに','をもとに','顧客アンケートの結果をもとに、新商品を開発した。','고객 설문 결과를 바탕으로 신상품을 개발했다.','manner')
  ) AS v(ord,pattern,meaning_ko,meaning_ja,formation,highlight,ja,ko,category)
  WHERE NOT EXISTS (SELECT 1 FROM jlpt_grammar WHERE jlpt_level='N2' AND pattern=v.pattern)
)
INSERT INTO jlpt_grammar (pattern, meaning_ko, meaning_ja, formation, category, example_sentences, jlpt_level, seq)
SELECT s.pattern, s.meaning_ko, s.meaning_ja, s.formation, s.category,
       jsonb_build_array(jsonb_build_object('ja', s.ja, 'ko', s.ko, 'highlight', s.highlight)),
       'N2', b.m + row_number() OVER (ORDER BY s.ord)
FROM src s CROSS JOIN base b;

-- 결과 확인
SELECT jlpt_level, count(*) FROM jlpt_grammar WHERE jlpt_level IN ('N1','N2') GROUP BY jlpt_level;
